<?php
// ---- ID encrypt / decrypt (AES-256-GCM, URL-safe token) ----
// IMPORTANT: ID_CRYPT_KEY dono files (index.php + ticketprice-new.php) me SAME rakhna aur random secret se badalna
if (!defined('ID_CRYPT_KEY')) {
    define('ID_CRYPT_KEY', 'CHANGE_ME_to_a_long_random_secret_key_123');
}
if (!function_exists('id_encrypt')) {
    function id_encrypt($id)
    {
        $key    = hash('sha256', ID_CRYPT_KEY, true);
        $iv     = random_bytes(12);
        $tag    = '';
        $cipher = openssl_encrypt((string) (int) $id, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag);
        return rtrim(strtr(base64_encode($iv . $tag . $cipher), '+/', '-_'), '=');
    }
}
if (!function_exists('id_decrypt')) {
    function id_decrypt($token)
    {
        $raw = base64_decode(strtr((string) $token, '-_', '+/'), true);
        if ($raw === false || strlen($raw) < 29) {
            return 0;
        }
        $key    = hash('sha256', ID_CRYPT_KEY, true);
        $iv     = substr($raw, 0, 12);
        $tag    = substr($raw, 12, 16);
        $cipher = substr($raw, 28);
        $plain  = openssl_decrypt($cipher, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag);
        return ($plain !== false && ctype_digit($plain)) ? (int) $plain : 0;
    }
}
/* =====================================================================
   AJAX REGISTRATION HANDLER (added)
   Form data insert karke JSON me new row ka id return karta hai.
   Normal page load pe ye block skip ho jata hai.
   ===================================================================== */
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['ajax_register'])) {
    ob_start();
    header('Content-Type: application/json; charset=utf-8');

    $respond = function (array $payload, int $status = 200) {
        if (ob_get_length()) { ob_clean(); }
        http_response_code($status);
        echo json_encode($payload);
        exit;
    };

    $field = function (array $keys, $default = '') {
        foreach ($keys as $key) {
            if (isset($_POST[$key]) && trim((string) $_POST[$key]) !== '') {
                return trim((string) $_POST[$key]);
            }
        }
        return $default;
    };

    $participant_name  = $field(['applicant-name']);
    $participant_age   = (int) $field(['participant_age']);
    $participant_email = $field(['applicant-email']);
    $participant_phone = $field(['participant_phone']);
    $institution       = $field(['visitor-organisation']);
    $guardian_name     = $field(['guardian_name']);
    $guardian_email    = $field(['guardian_email']);
    $guardian_phone    = $field(['guardian_phone']);
    $relationship      = $field(['relationship']);
    $referred_by       = $field(['referred_by']);
    $location          = $field(['location']);
    $message           = $field(['message']);

    // ---- server side validation ----
    if ($participant_name === '') {
        $respond(['success' => false, 'message' => 'Please enter the participant\'s name.'], 422);
    }
    if ($participant_age < 1 || $participant_age > 120) {
        $respond(['success' => false, 'message' => 'Please enter a valid age.'], 422);
    }
    if (!filter_var($participant_email, FILTER_VALIDATE_EMAIL)) {
        $respond(['success' => false, 'message' => 'Please enter a valid email address.'], 422);
    }
    if ($guardian_email !== '' && !filter_var($guardian_email, FILTER_VALIDATE_EMAIL)) {
        $respond(['success' => false, 'message' => 'Please enter a valid guardian email address.'], 422);
    }

    // ---- insert ----
    try {
        require_once __DIR__ . '/ccav/db.php';   // $conn (mysqli)

        $sql = "INSERT INTO participants_new
                (participant_name, participant_age, participant_email, participant_phone_number,
                 school_college_university, guardian_name, guardian_email, guardian_contact_number,
                 relationship_to_participant, referred_by, location, question_comment)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

        $stmt = $conn->prepare($sql);
        if (!$stmt) {
            throw new Exception($conn->error);
        }

        $stmt->bind_param(
            "sissssssssss",
            $participant_name,
            $participant_age,
            $participant_email,
            $participant_phone,
            $institution,
            $guardian_name,
            $guardian_email,
            $guardian_phone,
            $relationship,
            $referred_by,
            $location,
            $message
        );

        if (!$stmt->execute()) {
            throw new Exception($stmt->error);
        }

        $newId = (int) $conn->insert_id;
        $stmt->close();

        $respond(['success' => true, 'id' => id_encrypt($newId)]);
    } catch (Throwable $e) {
        error_log('EOS register insert failed: ' . $e->getMessage());
        $respond(['success' => false, 'message' => 'Could not save your registration. Please try again.'], 500);
    }
}
?>
