<script>
// Before/After toggle
function showScene(which){
  document.getElementById('scene-before').classList.toggle('active', which === 'before');
  document.getElementById('scene-after').classList.toggle('active', which === 'after');
  document.getElementById('btn-before').classList.toggle('active', which === 'before');
  document.getElementById('btn-after').classList.toggle('active', which === 'after');
}

// Session tabs
function showSession(n){
  document.querySelectorAll('.session-panel').forEach(p=>p.classList.remove('active'));
  document.querySelectorAll('.session-tab-card').forEach(t=>t.classList.remove('active'));
  document.getElementById('session-'+n).classList.add('active');
  document.querySelectorAll('.session-tab-card')[n-1].classList.add('active');
}

// Jump from a superpower card's "Day X · SY" tag straight to that session tab
function goToSession(e, n){
  e.preventDefault();
  showSession(n);
  document.getElementById('register').scrollIntoView({behavior:'smooth', block:'start'});
}

// Registration form — static preview only, no backend wired up yet
function handleRegisterSubmit(e){
  e.preventDefault();
  const form = document.getElementById('registerForm');
  const success = document.getElementById('formSuccess');
  form.querySelectorAll('.form-row, .section-label, .talk-coach-row, .recaptcha-box, .btn-register').forEach(el => el.style.display = 'none');
  success.classList.add('show');
}

// Coaches (generated as initials avatars) — duplicated once for a seamless scroll loop
const coaches = [
  "Chaitanya Kumar","Preeta Goel","Kamal Verma","Iram Rizvi","Jaisika Jabbal",
  "Anirudh Birla","Divya Muraleedhar","Manu Goel","Geet Kumar"
];
const grid = document.getElementById('coaches-grid');
const linkedinIcon = `<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M20.45 20.45h-3.56v-5.57c0-1.33-.02-3.04-1.85-3.04-1.86 0-2.14 1.45-2.14 2.94v5.67H9.34V9h3.41v1.56h.05c.48-.9 1.64-1.85 3.38-1.85 3.6 0 4.27 2.37 4.27 5.46v6.28zM5.34 7.43a2.07 2.07 0 1 1 0-4.13 2.07 2.07 0 0 1 0 4.13zM7.12 20.45H3.56V9h3.56v11.45z"/></svg>`;
const coachPhotos = {
  "Chaitanya Kumar": "data:image/png;base64,",
  "Preeta Goel": "data:image/png;base64,",
  "Kamal Verma": "data:image/png;base64,",
  "Iram Rizvi": "data:image/png;base64,",
  "Jaisika Jabbal": "data:image/png;base64,",
  "Anirudh Birla": "data:image/png;base64,",
  "Divya Muraleedhar": "data:image/png;base64,",
  "Manu Goel": "data:image/png;base64,",
  "Geet Kumar": "data:image/png;base64,"
};
[...coaches, ...coaches].forEach(name=>{
  const initials = name.split(' ').map(w=>w[0]).join('');
  const photoUrl = coachPhotos[name];
  const photoInner = photoUrl
    ? `<img src="${photoUrl}" alt="${name}" style="width:100%;height:100%;object-fit:cover;border-radius:12px;">`
    : initials;
  const div = document.createElement('div');
  div.className = 'coach';
  div.innerHTML = `
    <div class="coach-photo">${photoInner}</div>
    <div class="coach-info">
      <div class="coach-name">${name}</div>
      <div class="coach-divider"></div>
      <a class="coach-link" href="https://www.linkedin.com" target="_blank" rel="noopener">${linkedinIcon} LinkedIn</a>
    </div>
  `;
  grid.appendChild(div);
});

// Auto-scroll + manual arrow controls for the coaches row
const coachesScrollEl = document.getElementById('coaches-scroll');
const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let coachAutoTimer = null;
let coachResumeTimer = null;

function startCoachAutoScroll(){
  if(coachAutoTimer || prefersReducedMotion || !coachesScrollEl) return;
  coachAutoTimer = setInterval(()=>{
    coachesScrollEl.scrollLeft += 0.6;
    const half = coachesScrollEl.scrollWidth / 2;
    if(coachesScrollEl.scrollLeft >= half){
      coachesScrollEl.scrollLeft -= half;
    }
  }, 16);
}
function stopCoachAutoScroll(){
  clearInterval(coachAutoTimer);
  coachAutoTimer = null;
}
function scrollCoaches(direction){
  if(!coachesScrollEl) return;
  const card = coachesScrollEl.querySelector('.coach');
  const step = card ? (card.offsetWidth + 28) * 2 : 320;
  stopCoachAutoScroll();
  coachesScrollEl.scrollBy({left: direction * step, behavior:'smooth'});
  clearTimeout(coachResumeTimer);
  coachResumeTimer = setTimeout(startCoachAutoScroll, 3500);
}
if(coachesScrollEl){
  coachesScrollEl.addEventListener('mouseenter', stopCoachAutoScroll);
  coachesScrollEl.addEventListener('mouseleave', ()=>{
    clearTimeout(coachResumeTimer);
    startCoachAutoScroll();
  });
  startCoachAutoScroll();
}

// Generic auto-scroll + arrow controls for testimonial carousels (youth + parents)
const carouselTimers = {};
function startCarouselAuto(id){
  const el = document.getElementById(id);
  if(!el || prefersReducedMotion) return;
  if(carouselTimers[id] && carouselTimers[id].timer) return;
  carouselTimers[id] = carouselTimers[id] || {};
  carouselTimers[id].timer = setInterval(()=>{
    el.scrollLeft += 0.5;
    const half = el.scrollWidth / 2;
    if(el.scrollLeft >= half){
      el.scrollLeft -= half;
    }
  }, 16);
}
function stopCarouselAuto(id){
  if(carouselTimers[id] && carouselTimers[id].timer){
    clearInterval(carouselTimers[id].timer);
    carouselTimers[id].timer = null;
  }
}
function scrollCarousel(id, direction){
  const el = document.getElementById(id);
  if(!el) return;
  const card = el.querySelector('.testimonial-card, .paper-card-outer');
  const step = card ? (card.offsetWidth + 24) * 2 : 400;
  stopCarouselAuto(id);
  el.scrollBy({left: direction * step, behavior:'smooth'});
  carouselTimers[id] = carouselTimers[id] || {};
  clearTimeout(carouselTimers[id].resumeTimer);
  carouselTimers[id].resumeTimer = setTimeout(()=>startCarouselAuto(id), 3500);
}
['youthScroll','parentScroll'].forEach(id=>{
  const el = document.getElementById(id);
  if(!el) return;
  el.addEventListener('mouseenter', ()=>stopCarouselAuto(id));
  el.addEventListener('mouseleave', ()=>{
    clearTimeout(carouselTimers[id] && carouselTimers[id].resumeTimer);
    startCarouselAuto(id);
  });
  startCarouselAuto(id);
});
</script>
<script>(function(){const els=document.querySelectorAll("section:not(.hero) .section-head, section:not(.hero) .powers-grid, section:not(.hero) .session-grid-new, section:not(.hero) .stats-band, section:not(.hero) .testimonial-card, .eos-map-section .india-map-card, .form-card"); els.forEach(e=>e.classList.add("reveal-review")); const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add("is-visible");io.unobserve(x.target)}}),{threshold:.12}); els.forEach(e=>io.observe(e));})();</script>
<script>
(function(){
  document.querySelectorAll('.testimonial-read-more').forEach(function(btn){
    btn.addEventListener('click',function(){
      var text=btn.previousElementSibling;
      var expanded=btn.getAttribute('aria-expanded')==='true';
      btn.setAttribute('aria-expanded', String(!expanded));
      text.classList.toggle('is-expanded', !expanded);
      btn.textContent=expanded ? 'Read more' : 'Read less';
    });
  });
})();
</script>



<script>
/* ===== AJAX registration submit (added) =====
   Form -> index.php (insert) -> ticketprice-new.php?id=<new id>          */
(function () {
  var form = document.getElementById('registerForm');
  if (!form || !window.fetch || !window.FormData) return;   // fallback: normal POST to ticketprice-new.php

  var btn = form.querySelector('.btn-register');
  var err = document.getElementById('formError');

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    if (btn.disabled) return;                                // double click guard

    err.style.display = 'none';
    var oldText = btn.textContent;
    btn.disabled = true;
    btn.textContent = 'Submitting...';

    var fd = new FormData(form);
    fd.append('ajax_register', '1');

    fetch('index.php', {
      method: 'POST',
      body: fd,
      headers: { 'X-Requested-With': 'XMLHttpRequest' },
      credentials: 'same-origin'
    })
    .then(function (res) {
      return res.json().catch(function () {
        return { success: false, message: 'Unexpected response from server. Please try again.' };
      });
    })
    .then(function (data) {
      if (data && data.success && data.id) {
        window.location.href = 'ticketprice-new/' + encodeURIComponent(data.id);
      } else {
        throw new Error((data && data.message) || 'Something went wrong. Please try again.');
      }
    })
    .catch(function (ex) {
      err.textContent = ex.message || 'Network error. Please try again.';
      err.style.display = 'block';
      btn.disabled = false;
      btn.textContent = oldText;
    });
  });
})();
</script>
